import type { DiagnosisTraining, DiagnosisTrainingStep, TriText } from './diagnosis_training_types';

// JESSE_REWORKED_PERSONAL_TRAINING
// This file is protected from legacy replacement unless this exact id is being rebuilt.

type PlannedTrainingLocale = 'pt-BR' | 'vi' | 'id' | 'tr' | 'pl';

const tri = (
  ru: string,
  uk: string,
  es: string,
  planned: Partial<Record<PlannedTrainingLocale, string>> = {},
): TriText => {
  const copy: TriText = { ru, uk, es };
  for (const locale of ['pt-BR', 'vi', 'id', 'tr', 'pl'] as const) {
    if (planned[locale]) copy[locale] = planned[locale];
  }
  return copy;
};

function timeStep(input: {
  id: string;
  order: number;
  difficulty: DiagnosisTrainingStep['difficulty'];
  targetSkill: string;
  sentence: string;
  translation: TriText;
  options: string[];
  correctAnswer: string;
  correctFeedback: TriText;
  wrong: Record<string, TriText>;
  retry: [TriText, TriText, TriText];
  focusWords: string[];
}): DiagnosisTrainingStep {
  const correctIndex = input.options.findIndex((option) => option === input.correctAnswer);
  return {
    id: input.id,
    order: input.order,
    difficulty: input.difficulty,
    type: 'single_choice',
    targetSkill: input.targetSkill,
    translation: input.translation,
    explanationBlock: tri(
      'Не переводи предлог напрямую. Сначала определи тип времени: точка, день/дата или широкий период.',
      'Не перекладай прийменник напряму. Спочатку визнач тип часу: точка, день/дата або широкий період.',
      'No traduzcas la preposición directamente. Primero identifica el tipo de tiempo: punto, día/fecha o período amplio.',
      {
        'pt-BR': 'Não traduza a preposição diretamente. Primeiro identifique o tipo de tempo: ponto, dia/data ou período amplo.',
        vi: 'Đừng dịch giới từ trực tiếp. Trước tiên hãy xác định loại thời gian: điểm, ngày/ngày tháng hay khoảng thời gian rộng.',
        id: 'Jangan menerjemahkan preposisi secara langsung. Tentukan dulu jenis waktunya: titik waktu, hari/tanggal, atau periode luas.',
        tr: 'Edatı doğrudan çevirme. Önce zaman türünü belirle: nokta, gün/tarih ya da geniş dönem.',
        pl: 'Nie tłumacz przyimka bezpośrednio. Najpierw określ typ czasu: punkt, dzień/data albo szeroki okres.',
      },
    ),
    microTask: tri('Выбери правильный предлог времени.', 'Обери правильний прийменник часу.', 'Elige la preposición de tiempo correcta.', {
      'pt-BR': 'Escolha a preposição de tempo correta.',
      vi: 'Chọn giới từ thời gian đúng.',
      id: 'Pilih preposisi waktu yang benar.',
      tr: 'Doğru zaman edatını seç.',
      pl: 'Wybierz poprawny przyimek czasu.',
    }),
    sentence: input.sentence,
    answerOptions: input.options.map((text) => ({ id: text, text })),
    correctAnswerId: input.correctAnswer,
    correctIndex,
    correctFeedback: input.correctFeedback,
    wrongFeedbackByOption: Object.fromEntries(input.options
      .filter((option) => option !== input.correctAnswer)
      .map((option) => [option, input.wrong[option] ?? tri(
        'Не совсем. Проверь размер времени: at = точка, on = день/дата, in = широкий период.',
        'Не зовсім. Перевір розмір часу: at = точка, on = день/дата, in = широкий період.',
        'No exactamente. Revisa el tamaño del tiempo: at = punto, on = día/fecha, in = período amplio.',
        {
          'pt-BR': 'Não exatamente. Verifique o tamanho do tempo: at = ponto, on = dia/data, in = período amplo.',
          vi: 'Chưa hẳn. Kiểm tra độ rộng của thời gian: at = điểm, on = ngày/ngày tháng, in = khoảng thời gian rộng.',
          id: 'Belum tepat. Periksa ukuran waktunya: at = titik, on = hari/tanggal, in = periode luas.',
          tr: 'Tam değil. Zamanın boyutunu kontrol et: at = nokta, on = gün/tarih, in = geniş dönem.',
          pl: 'Nie całkiem. Sprawdź rozmiar czasu: at = punkt, on = dzień/data, in = szeroki okres.',
        },
      )])),
    retryFeedback: [
      input.retry[0],
      input.retry[1],
      input.retry[2],
      tri(
        `Подсказка: здесь нужен блок "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
        `Підказка: тут потрібен блок "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
        `Pista: aquí necesitas el bloque "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
        {
          'pt-BR': `Dica: aqui você precisa do bloco "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
          vi: `Gợi ý: ở đây cần cụm "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
          id: `Petunjuk: di sini perlu blok "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
          tr: `İpucu: burada "${input.correctAnswer} ${input.focusWords[0] ?? ''}" kalıbı gerekir.`.trim(),
          pl: `Podpowiedź: tutaj potrzebny jest blok "${input.correctAnswer} ${input.focusWords[0] ?? ''}".`.trim(),
        },
      ),
    ],
    fallbackExplanation: tri(
      'Лестница времени: at для маленькой точки на часах, on для дня или даты, in для месяца, года, сезона, части дня и будущего периода.',
      'Сходи часу: at для маленької точки на годиннику, on для дня або дати, in для місяця, року, сезону, частини дня і майбутнього періоду.',
      'Escalera de tiempo: at para un punto pequeño en el reloj, on para día o fecha, in para mes, año, estación, parte del día y período futuro.',
      {
        'pt-BR': 'Escada do tempo: at para um ponto pequeno no relógio, on para dia ou data, in para mês, ano, estação, parte do dia e período futuro.',
        vi: 'Bậc thang thời gian: at cho điểm nhỏ trên đồng hồ, on cho ngày hoặc ngày tháng, in cho tháng, năm, mùa, phần trong ngày và khoảng tương lai.',
        id: 'Tangga waktu: at untuk titik kecil pada jam, on untuk hari atau tanggal, in untuk bulan, tahun, musim, bagian hari, dan periode masa depan.',
        tr: 'Zaman merdiveni: at saatteki küçük nokta için, on gün ya da tarih için, in ay, yıl, mevsim, gün bölümü ve gelecek dönem için.',
        pl: 'Drabinka czasu: at dla małego punktu na zegarze, on dla dnia lub daty, in dla miesiąca, roku, pory roku, części dnia i okresu w przyszłości.',
      },
    ),
    focusWords: input.focusWords,
  };
}

